records = rl.all_manifest_records()
rows = cx.execute("select * from evidence_sources where verification_status='VERIFIED' order by ref_id").fetchall()
print('VERIFIED sources:', len(rows))
out={'pass':[], 'nohay':[], 'title_absent':[], 'notitle':[], 'nolines':[]}
fullfail=[]
for r in rows:
    ref=r['ref_id']
    if not rl.manifest_lines_for(ref, r['url'], r['doi'], records):
        out['nolines'].append(ref); continue
    lines,hays,why = rl._row_haystacks(r, records)
    if not hays:
        out['nohay'].append((ref,(r['doi'] or '')[:30], '; '.join(why)[:90])); continue
    titles=[rl._title_head(r[c]) for c in rl._TITLE_COLS if c in r.keys() and rl.normalise_quote(rl._title_head(r[c] or ''))]
    if not titles: out['notitle'].append(ref); continue
    if any(rl.normalise_quote(t) in h['flat'] for t in titles for _,h in hays): out['pass'].append(ref)
    else: out['title_absent'].append((ref,titles))
    full=[r[c] for c in rl._TITLE_COLS if c in r.keys() and r[c]]
    if not any(rl.normalise_quote(t) in h['flat'] for t in full for _,h in hays): fullfail.append((ref, full[0][:110], rl._title_head(full[0])[:60]))
for k,v in out.items():
    print(k, len(v))
    if k!='pass':
        for x in v: print('   ',x)
print('FULL stored title (not head) absent though head-or-none present:', len(fullfail))
for x in fullfail: print('   ',x)
